        testes.add(DynamicTest.dynamicTest("guias/instrucoes: obrigatório", () -> assertThrows(ErroDominio.class, () -> new GuiaPreparacao(Controle.novo(Estado.ATIVO), "Prepare seu ambiente de estudo", "Um roteiro simples para começar.", null, "oficinas-0"))));
