        testes.add(DynamicTest.dynamicTest("guias/oficina: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new GuiaPreparacao(Controle.novo(Estado.ATIVO), "Prepare seu ambiente de estudo", "Um roteiro simples para começar.", "1. Escolha um lugar confortável.\n2. Separe seu material.\n3. Leia as orientações da proposta.", "duas palavras"))));
        testes.add(DynamicTest.dynamicTest("leituras: exemplo válido", () -> assertDoesNotThrow(() -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/titulo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), null, "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/titulo: texto extenso", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/titulo: texto curto", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "x", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/autor: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", null, "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/autor: texto extenso", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/autor: texto curto", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "x", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/tipo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", null, "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/tipo: opção inválida", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Inexistente", "Capítulos 1 e 2", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/trecho: opcional", () -> assertDoesNotThrow(() -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", null, "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/trecho: texto extenso", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Obrigatória", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/obrigatoriedade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", null, 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/obrigatoriedade: opção inválida", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Inexistente", 1, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/ordem: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", null, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/ordem: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 0, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/ordem: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 51, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("leituras/oficina: obrigatório", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, null))));
        testes.add(DynamicTest.dynamicTest("leituras/oficina: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new LeituraComplementar(Controle.novo(Estado.ATIVO), "Pense em Python", "Allen B. Downey", "Livro", "Capítulos 1 e 2", "Obrigatória", 1, "duas palavras"))));
        testes.add(DynamicTest.dynamicTest("comunicados: exemplo válido", () -> assertDoesNotThrow(() -> new Comunicado(Controle.novo(Estado.ATIVO), "Bem-vindos ao Oficina Campus", "Um espaço para reunir ideias, orientações e informações sobre oficinas acadêmicas.", "Novidades"))));
        testes.add(DynamicTest.dynamicTest("comunicados/titulo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Comunicado(Controle.novo(Estado.ATIVO), null, "Um espaço para reunir ideias, orientações e informações sobre oficinas acadêmicas.", "Novidades"))));
        testes.add(DynamicTest.dynamicTest("comunicados/titulo: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Comunicado(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Um espaço para reunir ideias, orientações e informações sobre oficinas acadêmicas.", "Novidades"))));
        testes.add(DynamicTest.dynamicTest("comunicados/titulo: texto curto", () -> assertThrows(ErroDominio.class, () -> new Comunicado(Controle.novo(Estado.ATIVO), "x", "Um espaço para reunir ideias, orientações e informações sobre oficinas acadêmicas.", "Novidades"))));
        testes.add(DynamicTest.dynamicTest("comunicados/mensagem: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Comunicado(Controle.novo(Estado.ATIVO), "Bem-vindos ao Oficina Campus", null, "Novidades"))));
