        testes.add(DynamicTest.dynamicTest("comunicados/etiqueta: opcional", () -> assertDoesNotThrow(() -> new Comunicado(Controle.novo(Estado.ATIVO), "Bem-vindos ao Oficina Campus", "Um espaço para reunir ideias, orientações e informações sobre oficinas acadêmicas.", null))));
